<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {api} from '../api'
import {t,formatNumber,formatDate} from '../i18n'
import {useWorkspaceStore} from '../stores/workspace'
import {workloadRoleNames} from '../workload'
import {iterationSummaries,iterationSparkline,validIterationReport,type IterationReport,type IterationSummary} from '../workloadIterations'
import AppSelect from './AppSelect.vue'
const props=defineProps<{month:string;refreshKey?:number;disabled?:boolean}>()
const workspace=useWorkspaceStore(),report=ref<IterationReport|null>(null),mode=ref<'personal'|'organization'>('personal'),count=ref(4),role=ref('frontend'),project=ref(''),department=ref('*'),search=ref(''),threshold=ref(50),loading=ref(false),error=ref(''),page=ref(1),expanded=ref<string|null>(null)
let version=0,disposed=false,controller:AbortController|undefined
const blocked=computed(()=>props.disabled||workspace.identityConflict||workspace.operationDisabled||!workspace.currentUser||workspace.switchingProject)
const counts=computed(()=>[2,4,6,8,12].map(value=>({value,label:t('最近 {count} 次已完成迭代',{count:value})})))
const roles=computed(()=>Object.entries(workloadRoleNames).filter(([value])=>value!=='other').map(([value,label])=>({value,label:t(label)})))
const projects=computed(()=>[{value:'',label:t('全部可见项目')},...workspace.projects.map(p=>({value:p.id,label:p.name}))])
const departments=computed(()=>[{value:'*',label:t('所有部门')},...Array.from(new Map((report.value?.people||[]).map(p=>[p.departmentId,p.departmentName])).entries()).map(([value,label])=>({value,label:label||t('未分配部门')}))])
const thresholds=computed(()=>[30,50,100].map(value=>({value,label:t('波动阈值 ±{value}%',{value})})))
const allRows=computed(()=>report.value?iterationSummaries(report.value,role.value,threshold.value):[])
const matches=(p:{name:string;departmentId:string;departmentName:string})=>(department.value==='*'||p.departmentId===department.value)&&(!search.value.trim()||(p.name+' '+p.departmentName).toLocaleLowerCase().includes(search.value.trim().toLocaleLowerCase()))
const rows=computed(()=>allRows.value.filter(r=>matches(r.person))),pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/20))),visible=computed(()=>rows.value.slice((page.value-1)*20,page.value*20))
const noData=computed(()=>report.value?.people.filter(p=>!p.roles.some(r=>r.role===role.value)&&matches(p))||[])
const leaders=computed(()=>allRows.value.filter(r=>r.rank===1)),alertCount=computed(()=>rows.value.filter(r=>r.alerts.length>0).length)
const fmt=(n:number)=>formatNumber(n,{maximumFractionDigits:2})
function clear(){version++;controller?.abort();report.value=null;loading.value=false;error.value='';expanded.value=null}
async function load(){
 clear();if(disposed||blocked.value)return
 if(mode.value==='organization'&&!workspace.canViewReports){mode.value='personal';return}
 const expected={tenantId:workspace.session!.tenant.id,userId:workspace.currentUser!.id,month:props.month,count:count.value,scope:mode.value,project:project.value},request=version
 const current=()=>!disposed&&!blocked.value&&version===request&&workspace.session?.tenant.id===expected.tenantId&&workspace.currentUser?.id===expected.userId&&(expected.scope!=='organization'||workspace.canViewReports)
 controller=new AbortController();loading.value=true
 try {const data=await api<IterationReport>('/reports/workload/iterations?'+new URLSearchParams({month:expected.month,count:String(expected.count),scope:expected.scope,project:expected.project}),{signal:controller.signal});if(!current())return;if(!validIterationReport(data,expected))throw Error(t('趋势上下文校验失败，请重试'));report.value=data;if(mode.value==='personal'){const actual=data.people[0]?.roles;if(actual?.length&&!actual.some(r=>r.role===role.value))role.value=actual[0]!.role}}
 catch(e){if(current())error.value=e instanceof Error?e.message:t('趋势暂时无法读取，请重试')}
 finally{if(current())loading.value=false}
}
function graph(row:IterationSummary){return iterationSparkline(row.points)}
watch(()=>[props.month,props.refreshKey,props.disabled,mode.value,count.value,project.value,workspace.currentUser?.id,workspace.session?.tenant.id,workspace.identityConflict,workspace.operationDisabled,workspace.switchingProject,workspace.canViewReports],()=>{page.value=1;department.value='*';search.value='';void load()})
watch([role,department,search],()=>{page.value=1;expanded.value=null})
onMounted(()=>{void load();window.addEventListener('devflow-identity-changed',clear);window.addEventListener('devflow-auth-expired',clear)})
onBeforeUnmount(()=>{disposed=true;clear();window.removeEventListener('devflow-identity-changed',clear);window.removeEventListener('devflow-auth-expired',clear)})
</script>
<template>
 <section class="iteration-analysis" :aria-label="t('迭代权重趋势与预警')">
  <header><div><h2>{{t('迭代权重趋势与预警')}}</h2><p>{{t('按当前需求职能分摊权重回看已完成迭代，不是历史绩效或实际工时。')}}</p></div><button class="btn" :disabled="loading||blocked" @click="load">{{t('刷新')}}</button></header>
  <div class="analysis-modes" role="group" :aria-label="t('统计范围')"><button :class="{selected:mode==='personal'}" :disabled="blocked" @click="mode='personal'">{{t('我的迭代趋势')}}</button><button v-if="workspace.canViewReports" :class="{selected:mode==='organization'}" :disabled="blocked" @click="mode='organization'">{{t('全员趋势与角色排名')}}</button></div>
  <div class="analysis-filters"><label>{{t('迭代次数')}}<AppSelect :label="t('迭代次数')" v-model="count" :options="counts" :disabled="blocked"/></label><label>{{t('项目')}}<AppSelect :label="t('项目')" v-model="project" :options="projects" :disabled="blocked"/></label><label>{{t('职能')}}<AppSelect :label="t('职能')" v-model="role" :options="roles" :disabled="blocked"/></label><label>{{t('负荷波动提醒')}}<AppSelect :label="t('负荷波动提醒')" v-model="threshold" :options="thresholds" :disabled="blocked"/></label><template v-if="mode==='organization'"><label>{{t('部门')}}<AppSelect :label="t('部门')" v-model="department" :options="departments" :disabled="blocked"/></label><label>{{t('搜索成员')}}<input v-model="search" :placeholder="t('姓名或部门')" :disabled="blocked"></label></template></div>
  <p v-if="loading" role="status">{{t('正在计算迭代趋势…')}}</p><p v-else-if="error" role="alert" class="analysis-error">{{error}} <button class="btn" @click="load">{{t('重试')}}</button></p>
  <template v-else-if="report">
   <p class="analysis-context">{{t('截止 {date}，实际纳入 {count} 次已完成迭代',{date:report.asOf,count:report.iterations.length})}} · {{t('数据更新时间')}} {{formatDate(report.generatedAt)}}</p>
   <details class="analysis-method"><summary>{{t('查看迭代范围与计算口径')}}</summary><p>{{t('同职能多人均分权重；排名按已完成需求的分摊权重降序，同值并列。未估算、少于 2 次有效迭代及历史成员不参与排名。无工作不等于零贡献。')}}</p><p>{{t('波动比较最近一次与此前至少 2 次有效迭代的平均权重；仅用于核对负荷与分配，不自动认定过载或低绩效。跨项目权重标尺可能不同，建议选择同一项目比较。')}}</p><ol><li v-for="s in report.iterations" :key="s.id">{{s.projectName}} · {{s.name}} · {{s.endDate}}</li></ol></details>
   <div v-if="mode==='organization'" class="analysis-insights"><span>{{t('{count} 位成员有提醒',{count:alertCount})}}</span><span>{{t('{count} 位成员暂无该职能数据',{count:noData.length})}}</span><span v-if="leaders.length">{{t('当前职能已完成权重领先')}}：{{leaders.slice(0,3).map(r=>r.person.name).join('、')}}{{leaders.length>3?'…':''}} · {{fmt(leaders[0]!.delivered)}}</span><span v-if="report.unassignedRequirementCount||report.ambiguousSprintItemCount">{{t('存在未绑定人员或迭代归属不明的需求，请先核对数据。')}}</span></div>
   <p v-if="!report.iterations.length" class="analysis-empty">{{t('当前范围暂无已完成迭代，可调整月份或项目。')}}</p>
   <div v-else-if="visible.length" class="analysis-table-wrap" tabindex="0" :aria-label="t('迭代权重趋势表')"><table><thead><tr><th v-if="mode==='organization'">{{t('权重排名')}}</th><th>{{t('成员')}}</th><th>{{t('各次迭代权重')}}</th><th>{{t('已分配权重')}}</th><th>{{t('已完成权重')}}</th><th>{{t('权重完成率')}}</th><th>{{t('预警与分析')}}</th></tr></thead><tbody><template v-for="row in visible" :key="row.person.userId"><tr><td v-if="mode==='organization'"><span class="rank" :class="{leading:row.rank===1}">{{row.rank??'—'}}</span></td><td><b>{{row.person.name}}</b><small>{{row.person.departmentName}}</small><small v-if="!row.person.active">{{t('历史成员')}}</small><button class="analysis-expand" :aria-expanded="expanded===row.person.userId" @click="expanded=expanded===row.person.userId?null:row.person.userId">{{t('查看明细')}}</button></td><td><svg viewBox="0 0 240 80" role="img" :aria-label="t('已分配权重趋势，精确值见明细')"><path :d="graph(row).map(p=>p.path).join(' ')" fill="none" stroke="currentColor" stroke-width="2"/><circle v-for="(p,i) in graph(row)" :key="i" :cx="p.x" :cy="p.y" r="3"><title>{{fmt(p.value)}}</title></circle></svg><small>{{t('{count} 次有效样本',{count:row.samples})}}</small></td><td>{{fmt(row.weight)}}</td><td class="delivered">{{fmt(row.delivered)}}</td><td>{{row.completion===null?'—':fmt(row.completion)+'%'}}</td><td class="analysis-alerts"><span v-for="alert in row.alerts" :key="alert" class="analysis-warning">{{t(alert)}}</span><span v-if="!row.alerts.length">{{t('未触发波动提醒')}}</span><small v-if="row.change!==null">{{t('相对此前均值')}} {{row.change>0?'+':''}}{{fmt(row.change)}}%</small><small v-if="row.missing">{{t('{count} 项职能未估算',{count:row.missing})}}</small></td></tr><tr v-if="expanded===row.person.userId"><td :colspan="mode==='organization'?7:6"><div class="analysis-details"><article v-for="(point,i) in row.points" :key="point.sprintId"><b>{{report.iterations[i]!.name}}</b><small>{{report.iterations[i]!.projectName}} · {{report.iterations[i]!.endDate}}</small><span v-if="!point.hasData">{{t('无该职能数据')}}</span><template v-else><span>{{t('已分配权重')}}：{{point.estimatedRoleCount?fmt(point.weight):'—'}}{{point.unestimatedRoleCount?' '+t('数据不完整'):''}}</span><span>{{t('已完成权重')}}：{{point.estimatedRoleCount?fmt(point.deliveredWeight):'—'}}</span><span>{{t('关联需求')}}：{{point.requirementCount}} · {{t('已完成需求')}}：{{point.shippedRequirementCount}}</span></template></article></div></td></tr></template></tbody></table></div>
   <p v-else class="analysis-empty">{{t('当前筛选下暂无该职能数据，不生成排名。')}}</p>
   <footer v-if="pages>1"><button class="btn" :disabled="page<=1" @click="page--">{{t('上一页')}}</button>{{page}} / {{pages}}<button class="btn" :disabled="page>=pages" @click="page++">{{t('下一页')}}</button></footer>
   <details v-if="noData.length" class="analysis-method"><summary>{{t('查看暂无该职能数据的成员')}}</summary><p>{{noData.map(p=>p.name).join('、')}}</p></details>
  </template>
 </section>
</template>
<style scoped>
.iteration-analysis{margin:20px 0;padding:24px;border:1px solid var(--line);border-radius:14px;background:var(--surface);min-width:0}.iteration-analysis header{display:flex;gap:16px;align-items:flex-start;justify-content:space-between}.iteration-analysis h2{font-size:18px;margin:0 0 8px}.iteration-analysis p{font-size:13px;line-height:1.7;color:var(--muted)}.analysis-modes{display:flex;flex-wrap:wrap;gap:4px;margin:16px 0}.analysis-modes button{padding:9px 14px;border:0;border-radius:8px;background:transparent;color:var(--muted);font:inherit;cursor:pointer}.analysis-modes .selected{color:#2764de;background:#eaf1ff;font-weight:650}.analysis-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px}.analysis-filters label{display:grid;gap:6px;min-width:0;font-size:12px;color:var(--muted)}.analysis-filters input{width:100%;min-width:0;box-sizing:border-box;min-height:36px;border:1px solid var(--line);border-radius:6px;padding:8px;background:var(--surface);color:var(--text)}.analysis-insights{display:flex;gap:10px;flex-wrap:wrap;padding:14px 0;font-size:12px}.analysis-insights>span{padding:6px 10px;background:var(--surface-soft,#f4f7fc);border-radius:6px}.analysis-method{font-size:12px;color:var(--muted);padding:12px 0}.analysis-method summary{cursor:pointer;color:var(--brand,#326aed)}.analysis-table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px;max-height:680px}.iteration-analysis table{border-collapse:collapse;width:100%;min-width:850px;font-size:13px}.iteration-analysis th,.iteration-analysis td{padding:14px;text-align:left;border-bottom:1px solid var(--line);vertical-align:middle}.iteration-analysis th{position:sticky;top:0;background:var(--surface);z-index:1;white-space:nowrap;color:var(--muted);font-weight:500}.iteration-analysis small{display:block;font-size:11px;color:var(--muted);margin-top:6px}.iteration-analysis svg{width:180px;height:60px;display:block;color:#3975e9;fill:#3975e9}.analysis-alerts{min-width:230px;max-width:300px}.analysis-warning{display:block;color:#986313;background:#fff5df;padding:5px 8px;border-radius:5px;margin:3px 0;font-size:12px}.rank{display:inline-grid;place-items:center;min-width:24px;min-height:24px;border-radius:6px;font-variant-numeric:tabular-nums}.rank.leading{background:#eaf1ff;color:#2764de}.delivered{color:#2764de;font-weight:650}.analysis-expand{margin-top:8px;display:block;background:none;border:0;padding:0;color:var(--brand,#326aed);cursor:pointer;font-size:12px}.analysis-details{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;max-width:1200px}.analysis-details article{padding:12px;border:1px solid var(--line);border-radius:8px}.analysis-details span{display:block;font-size:12px;margin-top:8px}.analysis-empty{padding:30px;text-align:center}.analysis-error{color:#b73242!important}.iteration-analysis footer{display:flex;justify-content:flex-end;gap:12px;align-items:center;margin-top:12px}.iteration-analysis td{font-variant-numeric:tabular-nums}@media(max-width:700px){.iteration-analysis{padding:16px;margin:14px 0}.analysis-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.analysis-modes button{flex:1;font-size:13px}.iteration-analysis header{gap:8px}.analysis-table-wrap{max-height:600px}.analysis-details{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(prefers-reduced-motion:no-preference){.analysis-modes button{transition:background .16s,color .16s}}
</style>
